require_once __DIR__ . '/bootstrap_saas.php';saas_require_login();$orgs=saas_organizations_for_user(saas_user_id());if(!$orgs)saas_redirect('organization_create.php');$org=saas_current_organization();$orgId=(int)$org['id'];$tours=saas_tours_for_user(saas_user_id(),$orgId);if(!$tours)saas_redirect('tour_create.php');$tour=saas_current_tour();if(!$tour){saas_set_context($orgId,(int)$tours[0]['id']);$tour=saas_current_tour();}$db=saas_db();$tourId=(int)$tour['id'];$stats=['passengers'=>0,'paid'=>0,'expenses'=>0,'pending_intents'=>0];$q=$db->prepare("SELECT COUNT(*) passengers,COALESCE(SUM(CASE WHEN tp.status<>'CANCELLED' THEN 1 ELSE 0 END),0) active_passengers FROM tour_passengers tp WHERE tp.tour_id=?");$q->execute([$tourId]);$row=$q->fetch();$stats['passengers']=(int)$row['active_passengers'];$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_id=?');$q->execute([$tourId]);$stats['paid']=(float)$q->fetchColumn();$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE tour_id=?');$q->execute([$tourId]);$stats['expenses']=(float)$q->fetchColumn();$q=$db->prepare("SELECT COUNT(*) FROM payment_intents WHERE tour_id=? AND status='PENDING'");$q->execute([$tourId]);$stats['pending_intents']=(int)$q->fetchColumn();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=saas_h($org['name'])?> — Dashboard</title><style>body{font-family:Arial,sans-serif;background:#f5f7fb;margin:0;color:#172033}.top{background:#172033;color:#fff;padding:18px 28px;display:flex;justify-content:space-between;align-items:center}.wrap{max-width:1100px;margin:30px auto;padding:0 18px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card,.panel{background:#fff;border-radius:14px;padding:20px;box-shadow:0 5px 20px #0000000d}.num{font-size:28px;font-weight:700;margin-top:8px}.nav{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.nav a{background:#fff;padding:12px 15px;border-radius:10px;text-decoration:none;color:#172033}.muted{color:#667085}@media(max-width:850px){.cards{grid-template-columns:1fr 1fr}}@media(max-width:500px){.cards{grid-template-columns:1fr}}</style></head><body><header class="top"><strong><?=saas_h($org['name'])?></strong><span><?=saas_h($tour['name'])?></span></header><main class="wrap"><h1>Tour dashboard</h1><p class="muted">Manage this tour from one place.</p><div class="cards"><div class="card">Passengers<div class="num"><?=$stats['passengers']?></div></div><div class="card">Payments received<div class="num"><?=number_format($stats['paid'],2)?></div></div><div class="card">Expenses<div class="num"><?=number_format($stats['expenses'],2)?></div></div><div class="card">Pending payment requests<div class="num"><?=$stats['pending_intents']?></div></div></div><nav class="nav"><a href="saas_buses.php">Buses</a><a href="saas_seat_plan.php">Visual seat plan</a><a href="saas_passengers.php">Passengers</a><a href="saas_rooms.php">Rooms</a><a href="saas_features.php">Tour features</a><a href="saas_payments.php">Payments</a><a href="saas_payment_intents.php">Payment Requests</a><a href="saas_expenses.php">Expenses</a><a href="saas_public.php">Public page</a></nav><section class="panel"><h2><?=saas_h($tour['name'])?></h2><p><?=nl2br(saas_h($tour['description']??''))?></p><p class="muted"><?=saas_h($tour['start_date']??'')?><?=!empty($tour['end_date'])?' — '.saas_h($tour['end_date']):''?></p></section></main></body></html>